from typing import List, Tuple, Optional


def extract_headings(markdown: str) -> List[Tuple[int, str]]:
    result: List[Tuple[int, str]] = []
    lines = markdown.splitlines()
    in_fence = False
    fence_char: Optional[str] = None

    for line in lines:
        leading_spaces = len(line) - len(line.lstrip(' '))
        stripped = line.lstrip(' ')

        # Handle fenced code blocks
        if leading_spaces <= 3 and (stripped.startswith('```') or stripped.startswith('~~~')):
            fence_type = stripped[:3]
            if not in_fence:
                in_fence = True
                fence_char = fence_type
            elif fence_char == fence_type:
                in_fence = False
                fence_char = None
            continue

        if in_fence:
            continue

        # Check ATX heading rules
        if leading_spaces > 3:
            continue

        if not stripped.startswith('#'):
            continue

        hash_count = 0
        for ch in stripped:
            if ch == '#':
                hash_count += 1
            else:
                break

        if hash_count < 1 or hash_count > 6:
            continue

        rest = stripped[hash_count:]

        if rest == '':
            result.append((hash_count, ''))
        elif rest[0] in ' \t':
            title = rest.lstrip(' \t').rstrip()
            if title.endswith('#'):
                i = len(title) - 1
                while i >= 0 and title[i] == '#':
                    i -= 1
                if i < 0:
                    title = ''
                elif title[i] in ' \t':
                    title = title[:i].rstrip()
            result.append((hash_count, title))

    return result
